drop policy if exists "school admins manage assignment tasks" on public.school_assignment_tasks;
create policy "assignment tasks strict" on public.school_assignment_tasks for all to authenticated using(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']) or(teacher_id=auth.uid() and subject_id is not null and public.is_subject_teacher_for(class_id,subject_id))) with check(public.is_super_admin() or public.is_school_member(school_id,array['school_admin']) or(teacher_id=auth.uid() and subject_id is not null and public.is_subject_teacher_for(class_id,subject_id));
drop policy if exists "assignment students access" on public.school_assignment_submissions;
create policy "assignment submissions strict" on public.school_assignment_submissions for all to authenticated using(exists(select 1 from public.school_assignment_tasks t where t.id=task_id and(public.is_super_admin() or public.is_school_member(t.school_id,array['school_admin']) or t.teacher_id=auth.uid() or student_id=auth.uid()))) with check(exists(select 1 from public.school_assignment_tasks t where t.id=task_id and(public.is_super_admin() or public.is_school_member(t.school_id,array['school_admin']) or t.teacher_id=auth.uid() or student_id=auth.uid())));
drop policy if exists "question items scoped" on public.teacher_question_items;
create policy "question items scoped" on public.teacher_question_items for all to authenticated using(exists(select 1 from public.teacher_question_banks b where b.id=bank_id and(public.is_super_admin() or public.is_school_member(b.school_id,array['school_admin']) or b.teacher_id=auth.uid()))) with check(exists(select 1 from public.teacher_question_banks b where b.id=bank_id and(public.is_super_admin() or public.is_school_member(b.school_id,array['school_admin']) or b.teacher_id=auth.uid())));
drop policy if exists "cbt questions scoped" on public.school_cbt_exam_questions;
create policy "cbt questions teacher manage" on public.school_cbt_exam_questions for all to authenticated using(exists(select 1 from public.school_cbt_exams e where e.id=exam_id and(public.is_super_admin() or public.is_school_member(e.school_id,array['school_admin']) or e.teacher_id=auth.uid()))) with check(exists(select 1 from public.school_cbt_exams e where e.id=exam_id and(public.is_super_admin() or public.is_school_member(e.school_id,array['school_admin']) or e.teacher_id=auth.uid())));
drop policy if exists "cbt attempts scoped" on public.school_cbt_attempts;
create policy "cbt attempts student teacher" on public.school_cbt_attempts for all to authenticated using(student_id=auth.uid() or exists(select 1 from public.school_cbt_exams e where e.id=exam_id and(public.is_super_admin() or public.is_school_member(e.school_id,array['school_admin']) or e.teacher_id=auth.uid()))) with check(student_id=auth.uid() or exists(select 1 from public.school_cbt_exams e where e.id=exam_id and(public.is_super_admin() or public.is_school_member(e.school_id,array['school_admin']) or e.teacher_id=auth.uid())));
